source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            colors = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] not in (0, 1):
                    colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if not colors:
                continue
            color = min(colors)
            for y, x in cells:
                if 0 < y < h - 1 and 0 < x < w - 1 and all(
                    grid[yy][xx] != 0
                    for yy in range(y - 1, y + 2)
                    for xx in range(x - 1, x + 2)
                ):
                    out[y][x] = color
    return out
'''
